SELECT c1.name, SUM(oi.quantity) AS units FROM order_items oi JOIN orders o ON o.order_id = oi.order_id JOIN product_variants v ON v.variant_id = oi.variant_id JOIN products p ON p.product_id = v.product_id JOIN categories c3 ON c3.category_id = p.category_id JOIN categories c2 ON c2.category_id = c3.parent_category_id JOIN categories c1 ON c1.category_id = c2.parent_category_id WHERE NOT o.is_deleted AND o.status NOT IN ('cancelled', 'canceled', 'payment_failed') AND CAST(o.order_at AS DATE) BETWEEN DATE '2026-01-01' AND DATE '2026-03-31' GROUP BY c1.name ORDER BY units DESC LIMIT 3
